from math import gcd

class Fraction:
    """A class representing a fraction in simplest form."""
    def __init__(self, num, den):
        if den == 0: raise ZeroDivisionError("Denominator cannot be zero.")
        common = gcd(num, den)
        self.num, self.den = (num // common, den // common) if den > 0 else (-num // common, -den // common)

    def __repr__(self):
        return f"{self.num}/{self.den}"

    def __eq__(self, other):
        return isinstance(other, Fraction) and self.num == other.num and self.den == other.den

    def __hash__(self):
        return hash((self.num, self.den))

    def __add__(self, other):
        if not isinstance(other, Fraction): return NotImplemented
        return Fraction(self.num * other.den + other.num * self.den, self.den * other.den)

print(Fraction(2, 4) == Fraction(1, 2))

